import{_ as a,o as e,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Messenger Situation and Optimization - Chunsong Feng, Huawei","description":"","frontmatter":{"title":"Ceph Messenger Situation and Optimization - Chunsong Feng, Huawei","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Distributed Storage","Performance Optimization","RDMA","UCX"],"categories":["技术文章","存储技术","Ceph架构","网络优化","性能测试"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Messenger_Situation_and_Optimization_-_Chunsong_Feng_Huawei.md","filePath":"posts/2023/Ceph_Messenger_Situation_and_Optimization_-_Chunsong_Feng_Huawei.md","lastUpdated":1780459816000}'),n={name:"posts/2023/Ceph_Messenger_Situation_and_Optimization_-_Chunsong_Feng_Huawei.md"};function o(r,i,s,h,u,_){return e(),l("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-消息传递情况与优化" tabindex="-1">会议主题：Ceph 消息传递情况与优化 <a class="header-anchor" href="#会议主题-ceph-消息传递情况与优化" aria-label="Permalink to &quot;会议主题：Ceph 消息传递情况与优化&quot;">​</a></h4><h4 id="会议议程" tabindex="-1">会议议程： <a class="header-anchor" href="#会议议程" aria-label="Permalink to &quot;会议议程：&quot;">​</a></h4><ol><li><strong>当前RDMA消息模块的不足</strong></li><li><strong>在自消息模块中启用UCX（Unified Communication X）的措施</strong></li><li><strong>性能测试结果</strong></li></ol><h4 id="讨论内容" tabindex="-1">讨论内容： <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容：&quot;">​</a></h4><ol><li><p><strong>当前RDMA消息模块的问题</strong></p><ul><li>流量控制缺失导致性能波动。</li><li>数据复制问题在发送和接收路径中存在。</li><li>使用限制，客户端和服务器需要使用RDMA连接，但客户端通常没有RDMA设备。</li><li>固定长度消息使用影响效率。</li></ul></li><li><p><strong>UCX架构与关键设计</strong></p><ul><li>引入UCX堆栈，使用UCX连接客户端和服务器。</li><li>中断与轮询模型处理设备事件。</li><li>使用不同协议处理不同大小的消息。</li><li>选择实际消息API实现零拷贝接收。</li></ul></li><li><p><strong>自RDMA与UCX堆栈的运行模块</strong></p><ul><li>使用RDMA轮询线程和匹配工作者，共享QPL连接。</li><li>优化锁和会话调用，使用连接映射，消除日志需求。</li></ul></li><li><p><strong>零拷贝接收</strong></p><ul><li>实现两个映射分别处理小包和大包。</li><li>预分配内存提高接收效率。</li></ul></li><li><p><strong>性能测试</strong></p><ul><li>基准测试显示UCX堆栈表现出更好的性能和效率。</li><li>类性能测试使用RBDs测试，实现约20%的性能提升。</li></ul></li></ol><h4 id="未来计划" tabindex="-1">未来计划： <a class="header-anchor" href="#未来计划" aria-label="Permalink to &quot;未来计划：&quot;">​</a></h4><ul><li>性能调优，尝试更多协议和发送接收协议。</li></ul><h4 id="提问与回答" tabindex="-1">提问与回答： <a class="header-anchor" href="#提问与回答" aria-label="Permalink to &quot;提问与回答：&quot;">​</a></h4><ul><li>与TCP相比，性能提升约10%。</li><li>尚未进行延迟测试，但UCX可能提供更低的延迟。</li><li>RDMA代码集成问题，需要移除中间层以充分利用RDMA。</li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>计划在三周内创建拉取请求，将UCX消息传递整合到主分支。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>整合UCX消息传递。</li><li>进行延迟测试，特别是尾延迟，以展示UCX的优势。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>感谢所有参与者的贡献和讨论，会议圆满结束。</li></ul><p>[会议纪要结束]</p>',17)])])}const g=a(n,[["render",o]]);export{p as __pageData,g as default};
